def components(g):
 h,w=len(g),len(g[0]); bg=Counter(x for r in g for x in r).most_common(1)[0][0]; seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if (r,c) in seen or g[r][c]==bg: continue
   col=g[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    a,b=q.pop();cells.append((a,b))
    for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
     if 0<=x<h and 0<=y<w and (x,y) not in seen and g[x][y]==col:
      seen.add((x,y));q.append((x,y))
   comps.append((col,cells))
 return bg,comps

